# Optimized element-wise multiply with SiLU kernel
# Fuses: silu(a) * b into a single kernel

fused_silu_mul_cpp_source = """
#include <hip/hip_runtime.h>

__global__ void fused_silu_mul_kernel(const float* a, const float* b, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float a_val = a[idx];
        // SiLU: f(x) = x * sigmoid(x) = x / (1 + exp(-x))
        float silu = a_val / (1.0f + expf(-a_val));
        out[idx] = silu * b[idx];
    }
}

torch::Tensor fused_silu_mul_hip(torch::Tensor a, torch::Tensor b) {
    int size = a.numel();
    auto out = torch::zeros_like(a);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    fused_silu_mul_kernel<<<num_blocks, block_size>>>(a.data_ptr<float>(), b.data_ptr<float>(), out.data_ptr<float>(), size);

    return out;
}
"""

fused_silu_mul = load_inline(
