                    float x_val = x_ptr[h];
                    gate_val += x_val * gate_w[h];
                    up_val += x_val * up_w[h];
                }

                gate_shared[thread_idx] = gate_val;
                up_shared[thread_idx] = up_val;
            }
        }
        __syncthreads();

        // Now compute each output dimension
        for (int h_block = 0; h_block < hidden_size; h_block += TILE_SIZE) {
            int h_idx = h_block + thread_idx;
            if (h_idx < hidden_size && thread_idx < TILE_SIZE) {
                const float* down_w = down_proj + h_idx * intermediate_size;
                float result = 0.0f;

                // Accumulate over intermediate_size
                for (int i = 0; i < TILE_SIZE && (im_block + i) < intermediate_size; i++) {
                    float g = gate_shared[i];
                    // SiLU
                    float silu_g = g / (1.0f + expf(-g));
                    float u = up_shared[i];
                    result += silu_g * u * down_w[im_block + i];
                }

                atomicAdd(&output[token_idx * hidden_size + h_idx], result);
            }
        }
